/// <reference path="../pb_data/types.d.ts" />

// Invitations: pending by default, with a token generated by the server.
// The token is the only key of the member's answer link: cryptographically
// random (43 alphanumeric characters, about 256 bits), unrelated to any
// identifier or personal data, never chosen by a client and never changed.

onRecordCreate((e) => {
  e.record?.set("token", $security.randomString(43));
  e.next();
}, "invitations");

onRecordUpdate((e) => {
  const record = /** @type {core.Record} */ (e.record);
  if (record.getString("token") !== record.original().getString("token")) {
    throw new BadRequestError("Invalid invitation.", {
      token: new ValidationError("token_immutable", "Cannot be changed."),
    });
  }
  e.next();
}, "invitations");

onRecordValidate((e) => {
  if (!e.record?.getString("participation")) {
    e.record?.set("participation", "pending");
  }
  e.next();
}, "invitations");
